-- REVIEW ONLY. One CREATE OR REPLACE statement. Execute as SQL script in DBeaver.
USE auxiliares;
DELIMITER $$
CREATE OR REPLACE TRIGGER `TRG_FB_CONSULTAS_HIST_ALTA` AFTER INSERT ON `FB_CIU_CONSULTAS_WEB` FOR EACH ROW
BEGIN
IF NEW.VERSION<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='71_VERSION_INICIAL'; END IF;
INSERT INTO FB_CONSULTAS_HISTORIAL (ID_CONSULTA,VERSION,TIPO_OPERACION,USUARIO_MODIFICADOR_ID,DATOS_ANTERIORES,DATOS_NUEVOS) VALUES (NEW.ID_CONSULTA,NEW.VERSION,'CREACION',NEW.USUARIO_CREADOR_ID,NULL,JSON_OBJECT('id_consulta',CAST(NEW.`ID_CONSULTA` AS CHAR),'padron',NEW.`PADRON`,'padcod',CAST(NEW.`PADCOD` AS CHAR),'localidad_padron',NEW.`LOCALIDAD_PADRON`,'nombre_completo',NEW.`NOMBRE_COMPLETO`,'rel_cod',NEW.`REL_COD`,'tipo_documento',NEW.`TIPO_DOCUMENTO`,'documento',NEW.`DOCUMENTO`,'domicilio_calle',NEW.`DOMICILIO_CALLE`,'domicilio_puerta',NEW.`DOMICILIO_PUERTA`,'domicilio_block',NEW.`DOMICILIO_BLOCK`,'domicilio_apto',NEW.`DOMICILIO_APTO`,'domicilio_localidad',NEW.`DOMICILIO_LOCALIDAD`,'domicilio_departamento',NEW.`DOMICILIO_DEPARTAMENTO`,'telefono_1',NEW.`TELEFONO_1`,'tipo_telefono_1',NEW.`TIPO_TELEFONO_1`,'telefono_2',NEW.`TELEFONO_2`,'tipo_telefono_2',NEW.`TIPO_TELEFONO_2`,'telefono_3',NEW.`TELEFONO_3`,'tipo_telefono_3',NEW.`TIPO_TELEFONO_3`,'telefono_4',NEW.`TELEFONO_4`,'tipo_telefono_4',NEW.`TIPO_TELEFONO_4`,'telefono_5',NEW.`TELEFONO_5`,'tipo_telefono_5',NEW.`TIPO_TELEFONO_5`,'mail_1',NEW.`MAIL_1`,'mail_2',NEW.`MAIL_2`,'mail_3',NEW.`MAIL_3`,'mail_4',NEW.`MAIL_4`,'mail_5',NEW.`MAIL_5`,'tipo_consulta',NEW.`TIPO_CONSULTA`,'descripcion',NEW.`DESCRIPCION`,'usuario_creador_id',NEW.`USUARIO_CREADOR_ID`,'fecha_alta',NEW.`FECHA_ALTA`,'fecha_modificacion',NEW.`FECHA_MODIFICACION`,'version',NEW.`VERSION`,'usuario_modificador_id',NEW.`USUARIO_MODIFICADOR_ID`,'id_persona',CAST(NEW.`ID_PERSONA` AS CHAR),'id_persona_cp',CAST(NEW.`ID_PERSONA_CP` AS CHAR),'concod',CAST(NEW.`CONCOD` AS CHAR),'relacion_declarada',NEW.`RELACION_DECLARADA`,'domicilio_declarado_json',JSON_QUERY(NEW.`DOMICILIO_DECLARADO_JSON`,'$'),'referencias_cp_json',JSON_QUERY(NEW.`REFERENCIAS_CP_JSON`,'$'),'actualiza_contacto',NEW.`ACTUALIZA_CONTACTO`,'contacto_version_esperada',NEW.`CONTACTO_VERSION_ESPERADA`));
END$$
DELIMITER ;
